import { Entry } from '@napi-rs/keyring'

export class KeyChain {
    private readonly account = 'now-sdk'
    private _entry: Entry | null = null

    constructor(private readonly service: string) {}

    /**
     * Lazy initialization of Entry to avoid errors in environments
     * without secure storage (e.g., CI/CD containers)
     */
    private getEntry(): Entry {
        if (!this._entry) {
            this._entry = new Entry(this.service, this.account)
        }
        return this._entry
    }

    async getPassword(): Promise<string | null> {
        try {
            return this.getEntry().getPassword()
        } catch {
            return null
        }
    }

    async setPassword(password: string): Promise<void> {
        this.getEntry().setPassword(password)
    }

    async deletePassword(): Promise<boolean> {
        try {
            this.getEntry().deletePassword()
            return true
        } catch {
            return false
        }
    }
}
